import json, sys
tpl = open('reel.html').read()
head = tpl.split('<body>')[0]
script = tpl[tpl.index('<script>'):]
def scene(i, tag, items, tipk, tip):
    lis = ''.join(f'<li><b>{e}</b>{t}</li>' for e, t in items)
    return f'<div class="s" id="s{i}"><span class="tag">{tag}</span><ul>{lis}</ul><div class="tip"><strong>{tipk}:</strong> {tip}</div></div>'
def build(d, out):
    body = f'<div class="s" id="s0"><p class="k">{d["hook1"]}</p><p class="k" style="font-size:86px;margin-top:30px">{d["hook2"]}</p><div class="sub">שמרו לטיול הבא 📌</div></div>'
    for i, sc in enumerate(d['scenes'], 1): body += scene(i, *sc)
    body += '<div class="s" id="s4"><p class="k" style="font-size:88px">את המסלול הזה בונים <em>בחינם</em> תוך שניות</p><div class="phone"><img src="bud_home.png"></div><div class="bio">הקישור בביו ✈️</div><div class="small">מסע · מתכנן טיולים בעברית</div></div>'
    css = f'#s1{{background:linear-gradient(160deg,{d["c"][0]})}}#s2{{background:linear-gradient(160deg,{d["c"][1]})}}#s3{{background:linear-gradient(160deg,{d["c"][2]})}}'
    open(out, 'w').write(head.replace('</style>', css + '</style>') + '<body>' + body + script)
